#if APP_TESTS
using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Media;
namespace FileCompass {
 internal static class UsbDriveTests {
  internal static int Run(string root){Directory.CreateDirectory(root);var checks=new List<string>();MainWindow window=null;Window icons=null;Action<bool,string> check=(value,label)=>{if(!value)throw new Exception(label);checks.Add(label);};Action<Action,string> rejects=(action,label)=>{bool rejected=false;try{action();}catch(IOException){rejected=true;}check(rejected,label);};try{
   check(UsbDriveActions.DriveIndex(@"H:\")==7 && UsbDriveActions.DriveIndex(@"i:\")==8,"Windows Format receives exact drive letter index");
   foreach(string path in new[]{"H:",@"H:\Folder",@"\\server\share",@"\\.\PhysicalDrive1",""})rejects(()=>UsbDriveActions.DriveIndex(path),"Reject non-root format target: "+path);
   check(UsbDriveActions.OnRoots(@"H:\Photos\one.jpg",new[]{@"H:\",@"I:\"}),"Files on source volume are detected");
   check(UsbDriveActions.OnRoots(@"I:\",new[]{@"H:\",@"I:\"}),"Other partitions on same device are detected");
   check(!UsbDriveActions.OnRoots(@"C:\Backup\H",new[]{@"H:\"}),"Unrelated paths are excluded");
   var parents=new Dictionary<uint,uint>{{1,2},{2,3},{3,4}};Func<uint,uint?> parent=x=>parents.ContainsKey(x)?(uint?)parents[x]:null;
   Func<uint,string> ids=x=>x==1?@"SCSI\Disk":x==2?@"USBSTOR\Disk":x==3?@"USB\VID_1234&PID_5678\FLASH":@"USB\ROOT_HUB30";
   check(UsbDriveActions.FindEjectNode(1,parent,ids,x=>x==3)==3,"Safe removal selects removable parent of storage disk");
   check(UsbDriveActions.FindEjectNode(1,parent,ids,x=>x==1)==1,"Removable disk node is used directly when supported");
   rejects(()=>UsbDriveActions.FindEjectNode(1,parent,ids,x=>x==4),"USB root hub is never ejected");
   rejects(()=>UsbDriveActions.FindEjectNode(1,parent,x=>x==4?@"USB\VID_9999&PID_9999\HUB":ids(x),x=>x==4),"Traversal stops at physical USB device before external hub");
   rejects(()=>UsbDriveActions.FindEjectNode(1,x=>x==1?(uint?)2:1,ids,x=>false),"Cyclic device tree is rejected");
   check(UsbDriveActions.AncestorContains(1,3,parent),"Protected sibling disk can block shared parent removal");
   check(!UsbDriveActions.AncestorContains(1,99,parent),"Unrelated system disk ancestry does not block USB");
   rejects(()=>UsbDriveActions.AncestorContains(1,99,x=>x==1?(uint?)2:1),"Invalid protected device ancestry fails closed");
   var source=new ExtSource{Physical=true,Removable=true,Name="Demo USB flash disk",Device=@"\\.\PHYSICALDRIVE99",Token="DEMO|1024"};
   check(UsbDriveActions.Eligible(source,99,0,1),"Removable USB is eligible");check(!UsbDriveActions.Eligible(source,0,0,1),"System disk is excluded");check(!UsbDriveActions.Eligible(source,1,0,1),"Application disk is excluded");source.Removable=false;check(!UsbDriveActions.Eligible(source,99,0,1),"Fixed USB disk is excluded");source.Removable=true;
   var readRequest=new ExtRequest{Source=source,Action="scan"};var readLease=ExtIoGate.Enter(readRequest,CancellationToken.None);var paused=ExtIoGate.PauseAsync(source);check(readLease.Token.IsCancellationRequested&&!paused.IsCompleted,"Eject cancels a background EXT read and waits for its handle lease");rejects(()=>ExtIoGate.Enter(readRequest,CancellationToken.None),"New EXT reads are rejected while ejection is waiting");readLease.Dispose();NavigationTests.Wait(paused);using(paused.Result){check(ExtIoGate.IsPaused(source.Device),"EXT device remains paused throughout native removal");rejects(()=>ExtIoGate.Enter(readRequest,CancellationToken.None),"Background rediscovery cannot reopen a paused device");}using(var resumed=ExtIoGate.Enter(readRequest,CancellationToken.None))check(!resumed.Token.IsCancellationRequested&&!ExtIoGate.IsPaused(source.Device),"Failed or completed removal restores normal reader access");using(var export=ExtIoGate.Enter(new ExtRequest{Source=source,Action="export"},CancellationToken.None)){rejects(()=>ExtIoGate.PauseAsync(source).GetAwaiter().GetResult(),"A real EXT export blocks removal instead of being terminated");check(!export.Token.IsCancellationRequested,"Safe removal never cancels an active export");}
   check(DesktopIcons.FlashDriveIcon.IsFrozen && Object.ReferenceEquals(DesktopIcons.FlashDriveIcon,DesktopIcons.StockIcon(7)),"Flash drive uses the Windows removable-drive stock icon");
   foreach(var drive in DriveInfo.GetDrives()){if(drive.DriveType==DriveType.Removable)check(DesktopIcons.WindowsDriveIcon(drive.Name,false,true,true)!=null&&DesktopIcons.WindowsDriveIcon(drive.Name,false,true,true).IsFrozen,"Actual removable drive uses its frozen Windows shell icon: "+drive.Name);}
   SynchronizationContext.SetSynchronizationContext(new System.Windows.Threading.DispatcherSynchronizationContext(System.Windows.Threading.Dispatcher.CurrentDispatcher));
   string sample=Path.Combine(root,"demo-flash"),safe=Path.Combine(root,"safe-folder");Directory.CreateDirectory(sample);Directory.CreateDirectory(safe);File.WriteAllText(Path.Combine(sample,"Example.txt"),"Demonstration file");
   window=new MainWindow(safe,new ProgramSettings{AutoRefresh=false}){Left=-18000,Top=-18000,ShowActivated=false,ShowInTaskbar=false,WindowStartupLocation=WindowStartupLocation.Manual};window.Show();NavigationTests.WaitPanels(window);
   try{foreach(var drive in DriveInfo.GetDrives().Where(d=>d.DriveType==DriveType.Removable)){var device=UsbStorageDevice.Find(ExtDiskStream.DiskNumber(drive.Name));File.AppendAllText(Path.Combine(root,"hardware-discovery.txt"),drive.Name+" metadataNode="+device.Node+" usbFlash="+(device.Source!=null)+" eligible="+(UsbDriveActions.Resolve(drive.Name)!=null)+Environment.NewLine);}}catch(Exception diagnostic){File.WriteAllText(Path.Combine(root,"hardware-discovery.txt"),diagnostic.ToString());}
   var extMenu=window.CreateUsbDriveMenu("ext://test/",source,x=>{});check(extMenu.Items.OfType<MenuItem>().Any(x=>Convert.ToString(x.Header)==L.Text("usb.eject"))&&!extMenu.Items.OfType<MenuItem>().Any(x=>Convert.ToString(x.Header)==L.Text("usb.format")),"EXT partition menu allows physical ejection without offering Windows format");
   bool? command=null;var menu=window.CreateUsbDriveMenu(@"H:\",source,x=>command=x);var actions=menu.Items.OfType<MenuItem>().Where(x=>x.IsEnabled).ToArray();
   check(actions.Length>=2,"USB menu contains safe removal and Windows Format");actions[0].RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));check(command==false,"Safe removal invokes only eject callback");actions[1].RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));check(command==true,"Format invokes only format callback");
   typeof(MainWindow).GetField("busy",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).SetValue(window,true);var blocked=window.CreateUsbDriveMenu(@"H:\",source,x=>command=x);check(blocked.Items.OfType<MenuItem>().Where(x=>(string)x.Header==L.Text("usb.eject")||(string)x.Header==L.Text("usb.format")).All(x=>!x.IsEnabled),"USB actions are disabled while a file operation is running");typeof(MainWindow).GetField("busy",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).SetValue(window,false);
   var panel=FluentUiTests.Children<FilePanel>(window).First();panel.Navigate(sample,false);NavigationTests.Wait(panel.NavigationTask);NavigationTests.Wait(panel.ReleaseUsbRoots(new[]{sample+"\\"},safe));check(panel.CurrentPath==safe,"Panel leaves affected volume before removal or format");check(!UsbDriveActions.OnRoots(panel.CurrentPath,new[]{sample+"\\"}),"Panel no longer targets removable source");
   var row=new StackPanel{Orientation=Orientation.Horizontal,Margin=new Thickness(16)};row.Children.Add(new Image{Source=DesktopIcons.StockIcon(8),Width=48,Height=48,Margin=new Thickness(8)});row.Children.Add(new Image{Source=DesktopIcons.FlashDriveIcon,Width=48,Height=48,Margin=new Thickness(8)});icons=new Window{Content=row,Width=200,Height=115,Left=-18000,Top=-18000,ShowActivated=false};icons.Show();icons.UpdateLayout();NextStageTests.Draw(icons,Path.Combine(root,"disk-and-flash-icons.png"));icons.Close();icons=null;
   window.Close();window=null;File.WriteAllLines(Path.Combine(root,"result.txt"),checks.Concat(new[]{"PASS: "+checks.Count,"Native format/eject calls were never invoked."}));return 0;
  }catch(Exception ex){File.WriteAllLines(Path.Combine(root,"result.txt"),checks.Concat(new[]{"FAIL: "+ex}));return 1;}finally{if(icons!=null)icons.Close();if(window!=null)window.Close();}}
 }
}
#endif
